"""The calibration report: one table per song of the bars where the record differs."""


def _time(seconds):
    return f'{int(seconds // 60)}:{seconds % 60:04.1f}'


def report(results: dict) -> str:
    """Markdown for docs/recording-check/report.md from recording-check.json's content."""
    lines = ['# Recording check', '',
             'Bars where the record plays something other than the chart. `chord` bars become',
             'Unsure bars to check by ear; `rhythm` bars are the same chords on other beats.',
             'Generated by `server/check_recording.py`; do not edit by hand.', '',
             '| Song | Verdict | Shift | Score | Chord | Rhythm | Unchecked | Checked |',
             '|---|---|---|---|---|---|---|---|']
    for title, entry in results.items():
        kinds = [b['kind'] for b in entry['bars']]
        score = f"{entry['score']:.2f}" if entry.get('score') is not None else '–'
        lines.append(f"| {title} | {entry['verdict']} | {entry['shift']:+d} | {score} "
                     f"| {kinds.count('chord')} | {kinds.count('rhythm')} "
                     f"| {len(entry.get('unchecked', []))} | {entry['checked']} |")
    for title, entry in results.items():
        lines += ['', f'## {title}', '',
                  f"Recording: {entry['recording'] or 'none'}. Verdict: {entry['verdict']}. "
                  f"Shift: {entry['shift']:+d}.", '']
        unchecked = entry.get('unchecked', [])
        if unchecked:
            names = ', '.join(f"{u['section']} {u['bar']}" for u in unchecked)
            lines += [f'Unchecked (every play lost to a slipped line-up): {names}.', '']
        if not entry['bars']:
            lines.append('No findings.')
            continue
        lines += ['| Section | Bar (0 = first) | Chart | Record | Kind | Confidence | At |',
                  '|---|---|---|---|---|---|---|']
        for b in entry['bars']:
            at = ', '.join(_time(t) for t in b['at'])
            lines.append(f"| {b['section']} | {b['bar']} | {b['chords']} | {b['record']} "
                         f"| {b['kind']} | {b['confidence']:.2f} | {at} |")
    return '\n'.join(lines) + '\n'
